 repair(index,expected){return this.change(d=>{if(!d.owned.includes(index)||d.condition[index]!==expected||expected>=100)return false;const price=Math.ceil((100-expected)*2);if(d.cash<price)return false;d.cash-=price;d.condition[index]=100;return true})}
